const $=s=>document.querySelector(s),sleep=ms=>new Promise(r=>setTimeout(r,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(n=>n.toString(16).padStart(2,'0')).join('');
const files=['app.js','engine.js','censor.js','censor-backing.js','reverse-censor-plan.js','beatgrid.js','smart-sync.js','keylock-shadow-live.js','pitch-time-map.js','pcm-resample.js','warped-censor-harness.js'];
const identities=async()=>Object.fromEntries(await Promise.all(files.map(async f=>[f,await hash(await(await fetch(f,{cache:'no-store'})).arrayBuffer())])));
async function until(fn,label,ms=20000){const end=performance.now()+ms;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(10);}}
const click=s=>{assert($(s),'Missing '+s);$(s).click();},button=(n,a)=>`[data-deck="${n}"][data-action="${a}"]`,value=(s,v)=>{$(s).value=String(v);};
function key(up=false,target=document.body){target.dispatchEvent(new KeyboardEvent(up?'keyup':'keydown',{key:up?'u':'U',code:'KeyU',shiftKey:!up,bubbles:true,cancelable:true}));}
function base64(b){let s='';for(let n=0;n<b.length;n+=16384)s+=String.fromCharCode(...b.subarray(n,n+16384));return btoa(s);}
function measure(data,sr,from,to){let power=0;const a=Math.ceil(from*sr),b=Math.floor(to*sr),cross=[];assert(a>=0&&b<=data.length&&b>a,'Invalid declared window');for(let n=a;n<b;n++){power+=data[n]**2;if(n>a&&data[n-1]<0&&data[n]>=0)cross.push((n-1-data[n-1]/(data[n]-data[n-1]))/sr);}return{from,to,rms:Math.sqrt(power/(b-a)),hz:cross.length>3?(cross.length-1)/(cross.at(-1)-cross[0]):null};}
let app;
async function run(){
 const {engine,state}=app;$('#warp-censor-run').disabled=true;
 const report={startedAt:new Date().toISOString(),completed:false,criteria:{frequencyErrorHz:1,minimumRMS:.005,forwardClockStateSeconds:.01,muteAmplitudeRatio:[.60,.73]},scope:'Actual app Smart Sync/Censor across reversed90→150→120 source tempo sections, keylock on then off, +2semitones, original plus four prepared synthetic sources. No new model inference/native/physical/loop/quality/reference acceptance.',modes:[],checks:[],errors:[]};
 const reach=at=>until(()=>engine.ctx.currentTime>=at,'Declared audio time');
 try{
  report.sourceBefore=await identities();await engine.resume();engine.audioMonitor.mutePhysical(true);await until(()=>engine.audioMonitor.snapshot().physicalMuted,'Physical graph mute');await until(()=>!state.analysis,'Initial analysis');
  for(const d of state.decks)engine.pause(d);for(const bank of state.fx)for(const slot of bank)slot.on=false;engine.configureFX(state.fx,state.fxRoutes||[],state.decks.map(d=>(d.track?.bpm||120)*d.rate),state.fxTempo);
  const sr=48000,duration=18;
  function tone(index,amplitude){const b=engine.ctx.createBuffer(2,sr*duration,sr),a=b.getChannelData(index),hz=index?550:330;for(let n=0;n<a.length;n++)a[n]=amplitude*Math.sin(2*Math.PI*hz*n/sr);return b;}
  for(let i=0;i<2;i++){const d=state.decks[i];Object.assign(d.track,{bpm:120,grid:0,gridWarpMarkers:[],gridMarkers:[],duration,analyzed:true});Object.assign(d,{rate:1,position:3,keylock:false,keyShift:0,reverse:false,loop:false,slip:false,stemSlip:'off',sync:false,mode:'INT',level:.8,stems:[true,true,true,true],stemFX:[false,false,false,false]});engine.clearDeckScratchCache(i);engine.buffers.set(d.track.id,tone(i,.12));engine.mix(i,'level',.8);}
  engine.stemBuffers.set(state.decks[0].track.id,[tone(0,.04),tone(0,.04),tone(0,.04),tone(0,0)]);
  click(button(0,'grid'));for(const marker of [{time:1,bpm:150},{time:2,bpm:90}]){value('#grid-warp-time',marker.time);value('#grid-warp-bpm',marker.bpm);click('#grid-marker');}click('#grid-save');await until(()=>!$('#modal').open,'Grid saved');assert(state.decks[0].track.gridWarpMarkers.length===2,'Warp markers missing');
  click('[data-panel="settings"]');const sync=$('[data-setting="Sync Mode"]');sync.value='Smart Sync';sync.dispatchEvent(new Event('change',{bubbles:true}));click('#save-settings');click(button(0,'keyUp'));await until(()=>state.decks[0].keyShift===1,'Key+1');click(button(0,'keyUp'));await until(()=>state.decks[0].keyShift===2,'Key+2');
  await engine.recordStart();report.recordStart=engine.recordStarted;
  for(const locked of [true,false]){
   const d=state.decks[0],mode={keylock:locked,sections:[],sourceSemitones:2};report.modes.push(mode);
   if(d.keylock!==locked){click(button(0,'keylock'));await until(()=>d.keylock===locked,'Requested keylock');}
   for(const deck of state.decks.slice(0,2))await engine.seek(deck,3);
   click(button(1,'sync'));click(button(1,'play'));await until(()=>state.decks[1].playing&&!state.decks[1].processing,'Primary Play');click(button(0,'sync'));await until(()=>d.syncState==='armed','Secondary Sync armed before Play');click(button(0,'play'));await until(()=>d.playing&&!d.processing&&engine.voices.get(0)?.gridTimeline,'Warped Play');await reach(d.anchorTime+.05);
   mode.initialSyncState={sync:d.sync,state:d.syncState,role:d.syncRole};assert(d.sync&&d.syncState==='beat','Fixture did not enter Beat Sync before Censor');
   const forward=engine.voices.get(0),clock=engine.voiceClock(d,forward),pitch=330*2**(2/12),base=locked?pitch:pitch*4/3;mode.forwardSourceOutputs=forward.stemGains.length;mode.forwardStart=engine.ctx.currentTime;
   mode.sections.push({name:'before',from:engine.ctx.currentTime-engine.recordStarted+.15,to:engine.ctx.currentTime-engine.recordStarted+.55,expectedLeft:base});await sleep(650);
   key();await until(()=>engine.deckScratchRequests.get(0)?.ready&&engine.voices.get(0)?.censorReverse,'Warped Censor ready');const reverse=engine.voices.get(0);await reach(d.anchorTime+.02);assert(reverse.censorBacking.liveVoice===forward,'Forward owner replaced');assert(reverse.censorReverse.outputs.length===5,'Expected five source outputs');mode.reverseSnapshot=reverse.censorReverse.snapshot();
   const segments=reverse.censorReverse.clock.filter(s=>s.playing&&s.when>=d.anchorTime-1e-8);assert(segments.length===3,'Expected reversed three-section map');mode.scheduled=segments.map(s=>({when:s.when,position:s.position,rate:s.rate}));
   let prior=engine.position(d);
   for(let i=0;i<segments.length;i++){const s=segments[i];await reach(s.when+.12);assert(engine.voices.get(0)===reverse,'Reverse owner changed');assert(Math.abs(engine.audibleRate(d)-s.rate)<1e-6,'Wrong reversed local rate');const pos=engine.position(d);assert(pos<prior,'Reverse cursor did not decrease');prior=pos;assert(d.sync&&d.syncState==='beat','Censor dropped Smart Sync');mode.sections.push({name:'reverse-'+i,from:s.when-engine.recordStarted+.15,to:s.when-engine.recordStarted+.55,expectedLeft:locked?pitch:pitch*s.rate});await reach(s.when+.58);}
   click(button(0,'tab')+'[data-tab="Stems"]');click(button(0,'pad')+'[data-pad="0"]');assert(d.stems[0]===false,'Vocal mute did not apply');const muteAt=engine.ctx.currentTime;mode.sections.push({name:'reverse-vocal-muted',from:muteAt-engine.recordStarted+.05,to:muteAt-engine.recordStarted+.20,expectedLeft:locked?pitch:pitch});await reach(muteAt+.23);
   key(true,$('#search'));await until(()=>!engine.deckScratchRequests.has(0)&&engine.voices.get(0)===forward,'Restore forward owner');mode.return={actual:engine.position(d),expected:clock(engine.ctx.currentTime),originalVoiceRestored:engine.voices.get(0)===forward,originalGridRetained:engine.voices.get(0).gridTimeline===forward.gridTimeline};assert(Math.abs(mode.return.actual-mode.return.expected)<.01,'Forward clock did not survive Censor');assert(d.syncState==='beat','Return lost Beat Sync');
   const returned=engine.ctx.currentTime;mode.sections.push({name:'return-vocal-muted',from:returned-engine.recordStarted+.15,to:returned-engine.recordStarted+.55,expectedLeft:base});await reach(returned+.60);click(button(0,'pad')+'[data-pad="0"]');assert(d.stems.every(Boolean),'Restore all Stems');const all=engine.ctx.currentTime;mode.sections.push({name:'return-all',from:all-engine.recordStarted+.15,to:all-engine.recordStarted+.55,expectedLeft:base});await reach(all+.60);
   for(let i=0;i<2;i++){click(button(i,'play'));await until(()=>!state.decks[i].playing,'Pause mode');click(button(i,'syncOff'));}report.checks.push((locked?'Locked':'Unlocked')+' reversed rate map, actual source outputs and original forward owner restored');
  }
 }catch(error){report.errors.push({message:error.message,stack:error.stack});}
 finally{
  key(true);window.dispatchEvent(new Event('blur'));for(const d of state.decks)engine.pause(d);
  if(engine.recording){const blob=await engine.recordStop();if(blob){const bytes=new Uint8Array(await blob.arrayBuffer());report.recording={bytes:bytes.length,format:blob.type,sha256:await hash(bytes),base64:base64(bytes)};try{const b=await engine.ctx.decodeAudioData(bytes.buffer.slice(0));report.decoded={duration:b.duration,frames:b.length,sampleRate:b.sampleRate,channels:b.numberOfChannels};assert(b.numberOfChannels===2,'Expected stereo');for(let c=0;c<2;c++)for(const v of b.getChannelData(c))assert(Number.isFinite(v),'Nonfinite whole recording');
   for(const mode of report.modes){mode.audio=mode.sections.map(s=>({...s,channels:[0,1].map(c=>measure(b.getChannelData(c),b.sampleRate,s.from,s.to))}));assert(mode.audio.length===7,'Missing seven fixed sections');for(const w of mode.audio){assert(w.channels[0].rms>.005&&Math.abs(w.channels[0].hz-w.expectedLeft)<1,w.name+' left pitch/RMS failed');assert(w.channels[1].rms>.005&&Math.abs(w.channels[1].hz-550)<1,w.name+' opposite deck failed');}const baseline=mode.audio.find(x=>x.name==='return-all').channels[0].rms;mode.muteRatios=mode.audio.filter(x=>x.name.endsWith('vocal-muted')).map(x=>({name:x.name,ratio:x.channels[0].rms/baseline}));assert(mode.muteRatios.every(x=>x.ratio>=.60&&x.ratio<=.73),'Stem mute routing/amplitude failed');}
   report.checks.push('Fourteen whole-master pitch/other-deck windows and Stem mute/return amplitude ratios');
  }catch(error){report.errors.push({message:error.message,stack:error.stack});}}}
  report.sourceAfter=await identities();report.sourceStable=JSON.stringify(report.sourceBefore)===JSON.stringify(report.sourceAfter);report.completed=report.checks.length===3&&!report.errors.length&&report.sourceStable;report.finishedAt=new Date().toISOString();$('#warp-censor-original').textContent=JSON.stringify(report,null,2);$('#warp-censor-results').textContent=JSON.stringify({...report,recording:report.recording?{...report.recording,base64:'Retained in complete original'}:null},null,2);$('#warp-censor-status').textContent=report.completed?'Scoped warped Censor workflow passed; audio stopped':'Failed: '+report.errors.map(e=>e.message).join('; ');const link=$('#warp-censor-download');link.href=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));link.download='warped-censor-original.json';link.hidden=false;
 }
}
$('#warp-censor-run').onclick=()=>run();
async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[1].track,'Actual app');app=window.openPlay;$('#warp-censor-run').disabled=false;$('#warp-censor-run').textContent='Run one warped Censor workflow';}
boot().catch(error=>$('#warp-censor-status').textContent=error.message);
